"use client";

import { useEffect, useRef, useState } from "react";
import type { CSSProperties, HTMLAttributes } from "react";

export type DotCascadePattern = "rings" | "fibonacci" | "grid";

export interface DotCascadeProps extends Omit<HTMLAttributes<HTMLDivElement>, "color"> {
  /** How the dots are laid out on the sphere. */
  pattern?: DotCascadePattern;
  /** Diameter of the front-most dots in px. Back dots shrink automatically. */
  dotSize?: number;
  /** Number of rows / dot density. Higher = more dots. */
  density?: number;
  /** Canvas size in px (the orb is square). */
  size?: number;
  /** Seconds each row takes to complete its 360° turn. */
  duration?: number;
  /** Seconds between one row starting and the next row below it. */
  stagger?: number;
  /** Seconds the orb rests after the bottom row finishes, before the next wave. */
  gap?: number;
  /** Spin direction around the vertical axis. */
  direction?: "left" | "right";
  /** Tilt toward the viewer in degrees, so the top of the orb shows. */
  tilt?: number;
  /** Dot color, any CSS color. */
  color?: string;
  /** Opacity of the dots furthest away (0–1). Front dots are always 1. */
  backOpacity?: number;
  /** Coast to a stop on the current frame. Turning it back off eases the animation back up to speed. */
  paused?: boolean;
  /** Accessible name; the wrapper is role="status". */
  label?: string;
}

/** Seconds (roughly) a resting row takes to settle back square after a timing change knocked it off. */
const REALIGN = 0.12;

type Settings = GlobeSettings & Required<Pick<DotCascadeProps, "duration" | "stagger" | "gap" | "direction">>;

/** Every number the drawing reads, as the latest props want it. */
function targetsOf(s: Settings) {
  return {
    ...globeTargets(s),
    duration: s.duration,
    stagger: s.stagger,
    gap: s.gap,
    // Spin velocity sign; flipping it slows turning rows, stops them, and turns them back the other way.
    dir: s.direction === "left" ? 1 : -1,
  };
}

type Key = keyof ReturnType<typeof targetsOf>;

function buildShape(s: Settings) {
  const globe = buildGlobe(s);
  const layers = globe.rows + 1;
  return {
    ...globe,
    layers,
    // Each row's spin angle, accumulated so timing changes mid-turn bend the motion instead of jumping it.
    angles: new Float64Array(layers),
    layerSin: new Float64Array(layers),
    layerCos: new Float64Array(layers).fill(1),
  };
}

type Shape = ReturnType<typeof buildShape>;

const shape = { key: globeKey, build: buildShape };

function scene(): Scene<Settings, Key, Shape> {
  // Position within the current wave (0–1), advanced by rate so pausing coasts to a stop.
  let phase = 0;

  return {
    advance(dt, { v, layers: onScreen }) {
      const shapes = onScreen.map((layer) => layer.shape);
      const turn = Math.max(0.05, v.duration);
      const stagger = Math.max(0, v.stagger);
      // Sized for the tallest orb on screen, so a fading-out orb's rows still finish their turn.
      const cycle = (Math.max(...shapes.map((shape) => shape.layers)) - 1) * stagger + turn + Math.max(0, v.gap);
      const settle = 1 - Math.exp(-dt / REALIGN);
      const from = phase;
      const to = phase + (dt * v.rate) / cycle;

      // Each row runs one eased 360° turn, starting `stagger` seconds after the row above.
      const progress = (p: number, l: number) => {
        const whole = Math.floor(p);
        return whole + Math.min(1, Math.max(0, ((p - whole) * cycle - l * stagger) / turn));
      };
      const turnsAt = (p: number, l: number) => {
        const x = progress(p, l);
        const whole = Math.floor(x);
        return whole + easeInOutCubic(x - whole);
      };

      for (const shape of shapes) {
        for (let l = 0; l < shape.layers; l++) {
          let a = shape.angles[l] + (turnsAt(to, l) - turnsAt(from, l)) * Math.PI * 2 * v.dir;
          a %= Math.PI * 2;
          const x = progress(to, l) % 1;
          // A row at rest belongs square to the orb; ease it back if a timing change left it skewed.
          if (x === 0) a -= (a - Math.PI * 2 * Math.round(a / (Math.PI * 2))) * settle;
          shape.angles[l] = a;
          shape.layerSin[l] = Math.sin(a);
          shape.layerCos[l] = Math.cos(a);
        }
      }
      phase = to % 1;
    },
    draw(ctx, frame) {
      drawGlobe(ctx, frame, frame.size / 2 - Math.max(0, frame.v.dotSize), ({ layerSin, layerCos }) => ({ x, y, z, row }, out) => {
        const sinA = layerSin[row];
        const cosA = layerCos[row];
        // Spin the row around the vertical axis.
        out.x = x * cosA + z * sinA;
        out.y = y;
        out.z = -x * sinA + z * cosA;
      });
    },
  };
}

export function DotCascade({
  pattern = "rings",
  dotSize = 3,
  density = 12,
  size = 160,
  duration = 1.4,
  stagger = 0.08,
  gap = 0.6,
  direction = "left",
  tilt = 18,
  color = "#e4e4e7",
  backOpacity = 0.2,
  paused = false,
  label = "Thinking",
  ...rest
}: DotCascadeProps) {
  const settings: Settings = { pattern, dotSize, density, size, duration, stagger, gap, direction, tilt, color, backOpacity, paused };
  return <LoaderCanvas settings={settings} targets={targetsOf} shape={shape} scene={scene} label={label} {...rest} />;
}

export default DotCascade;

/** Seconds (roughly) a changed prop takes to glide to its new value. */
const SETTLE = 0.16;

/** Seconds (roughly) pausing takes to coast to a stop, and resuming to get back up to speed. */
const PAUSE_SETTLE = 0.3;

/** A value that glides toward its target on a critically damped spring: no jump, no overshoot. */
type Glide = { value: number; velocity: number; target: number };

function glide(value: number): Glide {
  return { value, velocity: 0, target: value };
}

function snap(g: Glide) {
  g.value = g.target;
  g.velocity = 0;
}

/** Moves `g` toward its target. Returns false once it has arrived and is at rest. */
function stepGlide(g: Glide, dt: number, time: number) {
  if (g.value === g.target && g.velocity === 0) return false;
  const omega = 2 / time;
  const x = omega * dt;
  const decay = 1 / (1 + x + 0.48 * x * x + 0.235 * x * x * x);
  const change = g.value - g.target;
  const temp = (g.velocity + omega * change) * dt;
  g.velocity = (g.velocity - omega * temp) * decay;
  g.value = g.target + (change + temp) * decay;
  if (Math.abs(g.value - g.target) < 1e-3 && Math.abs(g.velocity) < 1e-3) snap(g);
  return true;
}

/** The glided value of every target, plus the canvas `size` and the pause `rate` (0 paused, 1 running). */
type Values<K extends string> = Record<K | "size" | "rate", number>;

/** What a scene sees each frame. `layers` holds every shape on screen; more than one while a change cross-fades. */
interface Frame<S, K extends string, L> {
  settings: S;
  v: Values<K>;
  layers: { shape: L; fade: number }[];
  size: number;
}

interface Scene<S, K extends string, L> {
  /** Moves the scene's own clock on by `dt` seconds. Scale by `v.rate` so pausing coasts to a stop. */
  advance?(dt: number, frame: Frame<S, K, L>): void;
  /** Paints one frame onto a cleared canvas, already scaled to `size` px. */
  draw(ctx: CanvasRenderingContext2D, frame: Frame<S, K, L>): void;
}

interface LoaderCanvasProps<S extends { size: number; paused: boolean }, K extends string, L>
  extends Omit<HTMLAttributes<HTMLDivElement>, "color"> {
  /** The latest props. Read by `targets` and `shape` on every render, and by the scene every frame. */
  settings: S;
  /** Every number the scene reads, as the latest settings want it. Each glides to its new value. */
  targets: (s: NoInfer<S>) => Record<K, number>;
  /** Geometry rebuilt when its key changes; the old shape fades out while the new one fades in. */
  shape?: { key: (s: NoInfer<S>) => string; build: (s: NoInfer<S>) => L };
  /** Called once on mount; the returned scene keeps its own clock between frames. */
  scene: () => Scene<NoInfer<S>, K, L>;
  label: string;
}

/**
 * A square canvas that runs a scene: props glide instead of jumping, pausing coasts, shape changes
 * cross-fade, reduced motion holds still, and the loop sleeps once nothing is moving.
 */
function LoaderCanvas<S extends { size: number; paused: boolean }, K extends string, L>({
  settings,
  targets,
  shape,
  scene,
  label,
  className,
  style,
  ...rest
}: LoaderCanvasProps<S, K, L>) {
  const wrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  // Only the first size reaches the DOM through React; after that the loop glides it.
  const [initialSize] = useState(settings.size);
  const latest = useRef({ settings, targets, shape, scene });
  const wakeRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    latest.current = { settings, targets, shape, scene };
    wakeRef.current?.();
  });

  useEffect(() => {
    const wrapper = wrapperRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext("2d");
    if (!wrapper || !canvas || !ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 3);
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    const { settings: first, shape: shapeOf, scene: makeScene } = latest.current;
    const sceneNow = makeScene();
    const glides = {} as Record<string, Glide>;
    const v = {} as Values<K>;
    let shapes = shapeOf ? [{ key: shapeOf.key(first), shape: shapeOf.build(first), fade: glide(1) }] : [];
    const frameInfo: Frame<S, K, L> = { settings: first, v, layers: [], size: 1 };
    let shownSize = -1;
    let frame = 0;
    let last = 0;

    const targetsNow = () => {
      const { settings: s, targets } = latest.current;
      return { ...targets(s), size: s.size, rate: s.paused ? 0 : 1 } as Record<string, number>;
    };
    for (const [k, value] of Object.entries(targetsNow())) glides[k] = glide(value);

    /** Refreshes what the scene reads from the glides and shapes. */
    const read = () => {
      for (const k in glides) (v as Record<string, number>)[k] = glides[k].value;
      frameInfo.settings = latest.current.settings;
      frameInfo.layers = shapes.map(({ shape, fade }) => ({ shape, fade: fade.value }));
      frameInfo.size = Math.max(1, v.size);
    };

    const sync = () => {
      const { settings: s, shape: shapeOf } = latest.current;
      for (const [k, value] of Object.entries(targetsNow())) glides[k].target = value;
      if (shapeOf) {
        const key = shapeOf.key(s);
        if (key !== shapes[shapes.length - 1].key) {
          for (const shape of shapes) shape.fade.target = 0;
          const fade = glide(0);
          fade.target = 1;
          shapes.push({ key, shape: shapeOf.build(s), fade });
        }
      }
      // Reduced motion: hold still and apply changes at once.
      if (reduceMotion.matches) {
        glides.rate.target = 0;
        for (const g of Object.values(glides)) snap(g);
        for (const shape of shapes) snap(shape.fade);
      }
    };

    const draw = () => {
      read();
      const size = frameInfo.size;
      if (size !== shownSize) {
        shownSize = size;
        wrapper.style.width = wrapper.style.height = `${size}px`;
        canvas.style.width = canvas.style.height = `${size}px`;
        const px = Math.round(size * dpr);
        if (canvas.width !== px) canvas.width = canvas.height = px;
      }
      ctx.setTransform(canvas.width / size, 0, 0, canvas.width / size, 0, 0);
      ctx.clearRect(0, 0, size, size);
      sceneNow.draw(ctx, frameInfo);
      ctx.globalAlpha = 1;
    };

    const tick = (now: number) => {
      const dt = last ? Math.min(0.1, (now - last) / 1000) : 0;
      last = now;
      let moving = false;
      for (const [k, g] of Object.entries(glides)) if (stepGlide(g, dt, k === "rate" ? PAUSE_SETTLE : SETTLE)) moving = true;
      for (const shape of shapes) if (stepGlide(shape.fade, dt, SETTLE)) moving = true;
      shapes = shapes.filter((shape) => shape.fade.target > 0 || shape.fade.value > 0);

      if (sceneNow.advance) {
        read();
        sceneNow.advance(dt, frameInfo);
      }
      draw();
      // Sleep once everything has settled and the animation is paused.
      frame = moving || glides.rate.value > 0 ? requestAnimationFrame(tick) : 0;
    };

    const wake = () => {
      sync();
      if (frame) return;
      last = 0;
      frame = requestAnimationFrame(tick);
    };

    wakeRef.current = wake;
    reduceMotion.addEventListener("change", wake);
    sync();
    draw();
    wake();
    return () => {
      cancelAnimationFrame(frame);
      wakeRef.current = null;
      reduceMotion.removeEventListener("change", wake);
    };
  }, []);

  const wrapperStyle: CSSProperties = { width: initialSize, height: initialSize, ...style };

  return (
    <div ref={wrapperRef} role="status" aria-label={label} className={className} style={wrapperStyle} {...rest}>
      <canvas ref={canvasRef} style={{ width: initialSize, height: initialSize, display: "block" }} />
    </div>
  );
}

let probe: CanvasRenderingContext2D | null = null;

/** Resolves any CSS color to sRGB [r, g, b, a] by painting it into one pixel, so it can be blended. */
function parseColor(color: string): [number, number, number, number] {
  probe ??= document.createElement("canvas").getContext("2d", { willReadFrequently: true });
  if (!probe) return [228, 228, 231, 1];
  probe.clearRect(0, 0, 1, 1);
  probe.fillStyle = "#000"; // An invalid color leaves fillStyle as it was, so start from a known one.
  probe.fillStyle = color;
  probe.fillRect(0, 0, 1, 1);
  const [r, g, b, a] = probe.getImageData(0, 0, 1, 1).data;
  return [r, g, b, a / 255];
}

/** A CSS color as glide targets, so a color change blends instead of jumping. */
function colorTargets(color: string) {
  const [red, green, blue, alpha] = parseColor(color);
  return { red, green, blue, alpha };
}

/** The blended color as an opaque CSS color; its alpha is applied per dot through globalAlpha. */
function rgb(v: { red: number; green: number; blue: number }) {
  return `rgb(${v.red} ${v.green} ${v.blue})`;
}

/** How the dots are laid out on the sphere. */
type GlobePattern = "rings" | "fibonacci" | "grid";

/** Props every dot sphere takes. */
interface GlobeSettings {
  pattern: GlobePattern;
  dotSize: number;
  density: number;
  size: number;
  tilt: number;
  color: string;
  backOpacity: number;
  paused: boolean;
}

/**
 * A point on the unit sphere. `row` is its latitude row from the top (0 to `rows`); `step` is its
 * place in the pattern's own order, which on the spiral winds down the arms instead of the rows.
 */
type GlobePoint = { x: number; y: number; z: number; row: number; step: number };

/** Where `place` puts a point before the tilt, plus how much it shrinks (`size`) and dims (`dim`). */
type Placed = { x: number; y: number; z: number; size: number; dim: number };

/** Back dots are drawn at this fraction of `dotSize`. */
const BACK_SCALE = 0.35;

/** Rows the spiral stripe drops over one full turn around the orb, as a fraction of all rows. */
const SPIRAL_PITCH = 0.5;

function rowsOf(s: GlobeSettings) {
  return Math.max(3, Math.round(s.density));
}

function buildPoints(pattern: GlobePattern, rows: number) {
  const points: GlobePoint[] = [];

  if (pattern === "fibonacci") {
    // The spiral has no rows, so band dots by height into rows, and let the step follow its arms:
    // mixing height with how far around the orb a dot sits turns a wave into a diagonal stripe
    // winding down the sphere. The stripe's seam (where "around" wraps) sits at the back, where the dots are faintest.
    const count = Math.round(rows * rows * 1.25);
    const golden = Math.PI * (3 - Math.sqrt(5));
    const pitch = rows * SPIRAL_PITCH;
    for (let i = 0; i < count; i++) {
      const y = 1 - ((i + 0.5) / count) * 2;
      const r = Math.sqrt(1 - y * y);
      const a = i * golden;
      const x = Math.cos(a) * r;
      const z = Math.sin(a) * r;
      const around = Math.atan2(-x, z) / (Math.PI * 2) + 0.5;
      points.push({ x, y, z, row: Math.round(((1 - y) / 2) * rows), step: ((1 - y) / 2) * rows + around * pitch });
    }
    return { points, steps: rows + pitch };
  }

  // Rings and grid share latitude rows; each row moves as one, so its step is its row number.
  // Poles get a single dot each.
  points.push({ x: 0, y: 1, z: 0, row: 0, step: 0 }, { x: 0, y: -1, z: 0, row: rows, step: rows });
  const cols = rows * 2;
  for (let i = 1; i < rows; i++) {
    const lat = Math.PI / 2 - (i / rows) * Math.PI;
    const y = Math.sin(lat);
    const r = Math.cos(lat);
    // Rings keep even spacing along each row; grid keeps meridians aligned.
    const n = pattern === "grid" ? cols : Math.max(1, Math.round(cols * r));
    const offset = pattern === "grid" ? 0 : (i % 2) * (Math.PI / n);
    for (let j = 0; j < n; j++) {
      const a = (j / n) * Math.PI * 2 + offset;
      points.push({ x: Math.cos(a) * r, y, z: Math.sin(a) * r, row: i, step: i });
    }
  }
  return { points, steps: rows };
}

type GlobeShape = ReturnType<typeof buildGlobe>;

/** The sphere's points, plus scratch space for projecting and depth-sorting them each frame. */
function buildGlobe(s: GlobeSettings) {
  const rows = rowsOf(s);
  const { points, steps } = buildPoints(s.pattern, rows);
  return {
    points,
    rows,
    /** The last step on the orb, so a sweep from step 0 to `steps` crosses all of it. */
    steps,
    placed: points.map((): Placed => ({ x: 0, y: 0, z: 0, size: 1, dim: 1 })),
    order: points.map((_, i) => i),
  };
}

/** Identifies an orb's geometry; a pattern or density change cross-fades the old orb out while the new one fades in. */
function globeKey(s: GlobeSettings) {
  return `${s.pattern}:${rowsOf(s)}`;
}

/** The globe's own glide targets; spread these into a component's targets. */
function globeTargets(s: GlobeSettings) {
  return { ...colorTargets(s.color), dotSize: s.dotSize, tilt: s.tilt, backOpacity: s.backOpacity };
}

type GlobeKey = keyof ReturnType<typeof globeTargets>;

/**
 * Places, tilts, depth-sorts and paints every orb on screen. `placeFor` is called once per orb and
 * returns how to place each of its points; far dots shrink and fade, so only placement varies.
 */
function drawGlobe<S, K extends string, L extends GlobeShape>(
  ctx: CanvasRenderingContext2D,
  { v, layers, size }: Frame<S, K | GlobeKey, L>,
  radius: number,
  placeFor: (shape: L) => (point: GlobePoint, out: Placed) => void,
) {
  const dotSize = Math.max(0, v.dotSize);
  const backOpacity = v.backOpacity;
  const center = size / 2;
  const tiltRad = (v.tilt * Math.PI) / 180;
  const sinT = Math.sin(tiltRad);
  const cosT = Math.cos(tiltRad);

  ctx.fillStyle = rgb(v);
  for (const { shape, fade } of layers) {
    const { points, placed, order } = shape;
    const place = placeFor(shape);
    for (let i = 0; i < points.length; i++) {
      const p = placed[i];
      p.size = p.dim = 1;
      place(points[i], p);
      // Tilt toward the viewer, so the top of the orb shows.
      const { y, z } = p;
      p.y = y * cosT - z * sinT;
      p.z = y * sinT + z * cosT;
    }
    order.sort((i, j) => placed[i].z - placed[j].z);

    const alpha = v.alpha * fade;
    for (const i of order) {
      const p = placed[i];
      const depth = Math.min(1, Math.max(0, (p.z + 1) / 2)); // 0 = back, 1 = front
      const r = (dotSize / 2) * (BACK_SCALE + (1 - BACK_SCALE) * depth) * p.size;
      ctx.globalAlpha = alpha * (backOpacity + (1 - backOpacity) * depth) * p.dim;
      ctx.beginPath();
      ctx.arc(center + p.x * radius, center - p.y * radius, r, 0, Math.PI * 2);
      ctx.fill();
    }
  }
}

function easeInOutCubic(t: number) {
  return t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2;
}
